INSERT INTO p_amb_brand (act_id, slug, live, display_name, intro, about, audience, accent, logo_url, submit_platform, submit_url, submit_label, avoid_json, rules_json, season_json, show_inspo) VALUES ('act_1033194534145987', 'party-patch', 0, 'Party Patch', 'Party Patch is the patch she puts on before a night out so tomorrow still happens. We need videos that look like her real life: busy, social, funny and a little chaotic. Pick an angle below, film it your way, and submit it on TRYBE like always.', 'A vitamin-infused patch you stick on before drinks, for a better day after a night out. Scent-free, zero calories and water resistant. It comes in fun designs, including the new Halloween bundle: three designs, six patches.', 'Moms and women 30 to 50 with a packed calendar. She is not trying to party harder. She wants to enjoy tonight and still show up tomorrow: soccer at 8, school drop-off, work, the pumpkin patch with the kids.', '#1E88E5', NULL, 'TRYBE', NULL, 'Film this on TRYBE', '[{"title": "Talking to camera about hangovers while putting a patch on, with a text overlay", "why": "This is most of what we get. It all looks the same and none of it stands out in the feed."}, {"title": "Lying in bed or on the couch looking hungover", "why": "We sell a better tomorrow, not a bad one. Show her up and doing things."}, {"title": "Shots, heavy drinking, or anyone who looks drunk", "why": "It breaks ad rules and it is not our customer. A drink in hand at dinner or a party is fine."}, {"title": "Reading the claims off the pack", "why": "Show the moment it helps. Nobody stops scrolling for an ingredient list."}, {"title": "An unboxing with no story", "why": "Unboxings only work when they are for something: the girls trip, the party tonight."}]', '["Say \"for a better next day\" or \"so tomorrow still happens\". Never say it cures, prevents or stops hangovers.", "Show the patch going on before the night starts, where we can see it.", "Keep the patch visible in at least one shot: arm, shoulder or hip.", "Everyone on screen is 21 or older. No drinking and driving, ever.", "Film vertical, sound on, and show where you are in the first two seconds.", "Only film people who have agreed to be in your video."]', '{"title": "Halloween party season", "until": "Oct 31", "line": "Adult Halloween parties, couples costume nights and girls'' Halloween are the big moments this month, and the new Halloween bundle is what we are pushing. Film it this week so it can run all month.", "next": "Friendsgiving, Thanksgiving Eve and holiday parties, from Nov 1", "highlight": ["10-01", "10-31"], "show_chart": true}', 1);
