INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('95d4ce773b2b4341', 'act_1033194534145987', 'b81fc5612a568c96', 1, 1, 1, 'live', 'Scary good night, less scary morning', 'The adult Halloween party is mom''s night, and the pumpkin patch with the kids still happens in the morning.', 'The mom going to an adult costume party who has the family pumpkin patch booked for 9am.', 'Halloween bundle', 'Split screen', 'Relief', '["Scary good night. Less scary morning.", "Adult Halloween party tonight. Pumpkin patch with the kids at 9.", "Me at 10pm vs me at 9am. Same witch."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Split screen. Left: you in costume at the party, drink in hand, 10:14 PM on screen. Right: the same you at a pumpkin patch the next morning, kids running around, 9:02 AM."}, {"label": "Middle", "text": "Cut to getting ready: the patch goes on before the costume is finished. Close-up so the design reads."}, {"label": "Close", "text": "Back at the pumpkin patch. You lift the biggest pumpkin like it is nothing, patch pack in your pocket or bag."}]', 'TONIGHT: Halloween party / TOMORROW: pumpkin patch with the kids', 'Put both times on screen. The clock is the story.', 'Show the morning in bed. She is up and doing it.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('cfaf5f88f1105a85', 'act_1033194534145987', 'b81fc5612a568c96', 1, 2, 2, 'live', 'Because moms deserve Halloween too', 'The kids get Halloween every year. This is the night mom and her friends take it back.', 'A group of mom friends dressing up for their own Halloween night.', 'Halloween bundle', 'Group reaction', 'Belonging', '["Because moms deserve Halloween too.", "The kids had their Halloween. This one''s ours.", "The mom group chat said costumes are mandatory."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Friends in costume arriving at the door. One line to camera: the kids had theirs, this one''s ours."}, {"label": "Middle", "text": "Someone opens the Halloween bundle. Everyone picks a design (Momster, Resting Witch Face, Here for the Boos) and sticks it on. React to the names."}, {"label": "Close", "text": "Cheers shot with the patches visible. End on the group laughing."}]', NULL, 'Have everyone read their patch name out loud. The designs are funny, use that.', 'Film it alone. This one needs the group.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('979c93f83a06bd7d', 'act_1033194534145987', 'b81fc5612a568c96', 1, 3, 3, 'live', 'One bundle covers the whole group', 'One Halloween bundle covers girls'' Halloween night: three designs, six patches.', 'The friend who plans the girls'' Halloween night and likes bringing something for everyone.', 'Halloween bundle', 'Unboxing with a purpose', 'Belonging', '["Six patches, three designs, one very good girls night.", "I bought one Halloween bundle and covered the whole group.", "Party favors for the moms, not the kids."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Bundle in hand at the pregame, friends around you getting ready."}, {"label": "Middle", "text": "Hand them out one by one and say why each friend gets that design. Keep it quick and teasing."}, {"label": "Close", "text": "Everyone patched up, one group shot on the way out."}]', '3 designs. 6 patches. 1 girls night.', 'Say "six patches, three designs" out loud.', 'Unbox it alone on a table with no one around.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('555c141c76942042', 'act_1033194534145987', 'b81fc5612a568c96', 0, 0, 4, 'live', 'Which patch are you?', 'Each Halloween design is a personality, and picking yours is half the fun.', 'Anyone who loves a "which one are you" moment with her friends.', 'Halloween bundle', 'Trend', 'Curiosity', '["Tell me you''re a Momster without telling me you''re a Momster.", "Which one are you: Momster, Resting Witch Face or Here for the Boos?", "I let my friends pick my Halloween patch and I am offended."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Hold up the three designs to camera and ask which one you are."}, {"label": "Middle", "text": "Friends or your partner vote. Quick cuts of each reaction."}, {"label": "Close", "text": "Stick on the one they picked, act offended, then own it."}]', 'Which one are you?', 'Ask the same question in your caption. It gets comments.', NULL, 'Any "which one are you" or pointing trend sound.');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('7db81e785adb7631', 'act_1033194534145987', 'b81fc5612a568c96', 0, 0, 5, 'live', 'He said he did not need one', 'Couples costume night is the one night you both go out, and you both still have to parent tomorrow.', 'Couples going to a costume party with kids at home.', 'Halloween bundle', 'Skit', 'Humour', '["We did a couples costume. We also both have a 7am wake-up call.", "Husband said he doesn''t need one. Watch.", "Matching costumes. Only one of us wore a patch."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Couple in matching costumes. She sticks her patch on and offers him one. He waves it off."}, {"label": "Middle", "text": "Cut to the morning: she is up making pancakes for the kids. He is moving a lot slower. Keep it playful."}, {"label": "Close", "text": "He holds his hand out for a patch for next time. She hands it over with a look."}]', 'He said he didn''t need one.', 'Keep it light. The joke is on him, not on drinking.', 'Make the morning look like a sick day.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('3bcc4dda4db52aeb', 'act_1033194534145987', 'b81fc5612a568c96', 0, 0, 6, 'live', 'Get ready with me: Halloween party', 'The patch is part of getting ready, like the lashes and the costume.', 'The mom going to her first adult Halloween party in years.', 'Halloween bundle', 'Get ready with me', 'Identity', '["Get ready with me for my first adult Halloween party in five years.", "Costume, lashes, patch. In that order.", "Mom by day. Witch by night."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Mirror, half in costume. Say where you are going tonight."}, {"label": "Middle", "text": "Makeup and costume in fast cuts. The patch goes on as its own step, close-up on the design."}, {"label": "Close", "text": "Full costume reveal with the patch visible on your arm or shoulder, then walk out."}]', NULL, 'Make the patch a real step in the routine, not an afterthought.', NULL, 'Any trending get ready with me or transformation sound.');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('97eb285995249148', 'act_1033194534145987', '625055be0a052dc2', 1, 4, 1, 'live', 'Your calendar doesn''t care what you did last night', 'Tomorrow is already booked, so she wears a patch tonight and still shows up.', 'The mom of school-age kids whose Saturday starts on a soccer sideline.', 'Party Patch', 'Split screen', 'Relief', '["Your calendar doesn''t care what you did last night.", "9:47 PM: margaritas with the girls. 8:03 AM: soccer sideline.", "Girls night was last night. Soccer is at 8. I''m fine."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Split screen. Left: 9:47 PM, you and your friends laughing over drinks at dinner. Right: 8:03 AM, the same you on the sideline in sunglasses with a big coffee cup."}, {"label": "Middle", "text": "Quick cut back to dinner: the patch goes on before the first drink. Close-up."}, {"label": "Close", "text": "Sideline: you cheer for your kid. Patch pack in your bag or on the chair."}]', 'TONIGHT: girls night / TOMORROW: 8AM soccer', 'Put the times on screen, and keep her looking good in both halves.', 'Show her tired or hurting in the morning. The point is she is fine.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('ecd251863af99459', 'act_1033194534145987', '625055be0a052dc2', 1, 5, 2, 'live', 'Game day, next day', 'A tailgate is an all-day event, and Sunday still shows up.', 'Women 30 to 45 who tailgate college or NFL games and have a full morning after.', 'Party Patch', 'Split screen', 'Relief', '["Game day. Next day.", "Tailgate Saturday. Pickleball at 8 on Sunday.", "Sunday Funday. Monday still happens."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Tailgate: jersey, friends, cooler. The patch is on your arm and in frame."}, {"label": "Middle", "text": "Hard cut to the next morning: pickleball court, church, or your desk on Monday. Same person, energy up."}, {"label": "Close", "text": "Hold up the patch pack where you are."}]', 'GAME DAY. NEXT DAY.', 'Wear team colours. Game day content travels.', 'Show shotgunning or drinking games.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('9814cd5ad095dc59', 'act_1033194534145987', '625055be0a052dc2', 0, 0, 3, 'live', 'Rosé tonight, rally tomorrow', 'League night drinks and an 8am match can both happen.', 'The pickleball or tennis league player who never skips the social after.', 'Party Patch', 'Day in the life', 'Relief', '["Ros\u00e9 tonight. Rally tomorrow.", "Wine with the league tonight. Match at 8. Let''s see.", "My pickleball team is 50 percent pickleball and 50 percent ros\u00e9."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Wine with your league friends. The patch goes on."}, {"label": "Middle", "text": "Next morning: the court, first serve."}, {"label": "Close", "text": "Win a point, celebrate, patch visible on your arm."}]', NULL, NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('fc20bb260eec696a', 'act_1033194534145987', '625055be0a052dc2', 0, 0, 4, 'live', 'She''s got stuff to do', 'Her week is full, so a big night cannot cost her a day.', 'The busy woman whose Friday night and Saturday morning are both booked.', 'Party Patch', 'Voiceover montage', 'Identity', '["She has dinner at 8. And soccer at 8.", "Cocktails Friday. Pickleball Saturday. She has stuff to do.", "Friendsgiving tonight. Thanksgiving tomorrow. She has things to do."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Fast montage, one line per shot: dinner, soccer, cocktails, pickleball, school run."}, {"label": "Middle", "text": "Every \"tonight\" shot shows the patch going on."}, {"label": "Close", "text": "End on her walking fast with a coffee: she has stuff to do."}]', 'She''s got stuff to do.', 'Keep the cuts fast, one second a shot.', 'Swear in the on-screen text. The edgier line is fine out loud if it fits your audience.', 'A fast-cut beat or a trending "that girl" routine sound.');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('d0266ff6900f71f0', 'act_1033194534145987', '625055be0a052dc2', 0, 0, 5, 'live', 'Because the babysitter wasn''t cheap', 'Date night is rare, so it has to count, and tomorrow still starts at 7.', 'Parents on a rare night out.', 'Party Patch', 'Skit', 'Humour', '["Because the babysitter wasn''t cheap.", "We finally got a sitter. We are making it count.", "Date night tonight. 7am spin tomorrow."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Paying the babysitter at the door, wide-eyed at the total."}, {"label": "Middle", "text": "At dinner: both of you put a patch on. Cheers."}, {"label": "Close", "text": "Morning: spin class or the kids jumping on the bed, and you are up for it."}]', 'We are making this date night count.', NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('2fa5f070f5159d67', 'act_1033194534145987', '625055be0a052dc2', 0, 0, 6, 'live', 'Wedding tonight, brunch tomorrow', 'Fall wedding season means dancing until midnight and a brunch at 10.', 'Bridesmaids and guests at fall weddings.', 'Party Patch', 'Get ready with me', 'Relief', '["Wedding tonight. Brunch tomorrow.", "Bridesmaid duties: dress, hair, patch.", "Dancing until midnight. Brunch at 10. Here is how."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Getting ready in the wedding outfit. The patch goes on your shoulder or hip under the dress."}, {"label": "Middle", "text": "Dance floor clips."}, {"label": "Close", "text": "Next morning at brunch, fresh, laughing with the group."}]', NULL, 'Show where the patch hides under a dress. People ask.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('d5055c6bbc83ca6d', 'act_1033194534145987', 'f277e283a01e9fa3', 0, 0, 1, 'live', 'Let me show you my October', 'From September to December her calendar is relentless, and every event is a night out.', 'The mom who said yes to everything this fall.', 'Party Patch', 'Screen record', 'Relatability', '["Let me show you my October.", "This is the calendar of a mom who said yes to everything.", "Every square on this calendar is a night out. Every next morning is booked."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Screen record your real calendar (hide anything private) and scroll through a packed month."}, {"label": "Middle", "text": "Tap into events: bunco, book club, a wedding, a tailgate, a Halloween party. Quick clip of each."}, {"label": "Close", "text": "Hold up the patch pack: this is how I get through it."}]', 'My October, a thread', NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('f24e0fab5b2cf005', 'act_1033194534145987', 'f277e283a01e9fa3', 0, 0, 2, 'live', 'Book club is just wine club', 'Book club is a wine night, everybody knows it, and school drop-off is at 7:45.', 'Book club moms.', 'Party Patch', 'Skit', 'Humour', '["Book club: ten minutes on the book, two hours on the wine.", "Nobody finished the book. Everybody brought wine.", "We read the room, not the book."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Book club table, books closed, wine poured."}, {"label": "Middle", "text": "One friend hands out patches: we know how this goes."}, {"label": "Close", "text": "Next morning: school drop-off, waving, fine."}]', NULL, NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('c32da0c6e2e0f7de', 'act_1033194534145987', 'f277e283a01e9fa3', 0, 0, 3, 'live', 'Bunco got a little competitive', 'Neighborhood game nights get loud, and the carpool still leaves at 7:30.', 'Neighborhood bunco and game night groups.', 'Party Patch', 'Group reaction', 'Belonging', '["Bunco got a little competitive.", "Neighborhood bunco night. The stakes are high.", "We came for bunco. We stayed for the wine."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Dice rolling, someone yelling bunco."}, {"label": "Middle", "text": "Patches going on around the table between rounds."}, {"label": "Close", "text": "Morning carpool line, waving at the same friends."}]', NULL, NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('4db9b0cbeff0871e', 'act_1033194534145987', 'f277e283a01e9fa3', 0, 0, 4, 'live', 'Girls trip insurance', 'The patch is the one thing on the packing list that protects every day of the trip.', 'Women planning a girls weekend or a bachelorette.', 'Party Patch', 'What is in my bag', 'Loss', '["Girls trip packing list. The most important thing is at the end.", "Girls trip insurance.", "I packed one for every night of the trip."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Packing montage: outfits, sunscreen, shoes."}, {"label": "Middle", "text": "Last item: count out a patch for each night."}, {"label": "Close", "text": "At the destination, the group puts them on before night one."}]', 'Girls trip insurance', NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('0ffc9ae2a4f2c08c', 'act_1033194534145987', 'f277e283a01e9fa3', 0, 0, 5, 'live', 'Encore tonight, real life tomorrow', 'Forty and at a concert singing every word, with a school run at 7:45.', 'Girlfriends 35 to 50 at a concert.', 'Party Patch', 'Day in the life', 'Identity', '["Encore tonight. Early morning tomorrow.", "Forty, front row, every word. School run at 7:45.", "We are too old for this and we are doing it anyway."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Singing at the concert with your friends."}, {"label": "Middle", "text": "Flash back to the car before the show: patches on."}, {"label": "Close", "text": "Morning routine, still humming the song, kids out the door."}]', NULL, NULL, NULL, 'Use the artist''s song only if the platform allows it; otherwise a trending sound.');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('cb0b270696b917cd', 'act_1033194534145987', 'f277e283a01e9fa3', 0, 0, 6, 'live', 'What time is your alarm tomorrow?', 'Everyone at a party has something tomorrow.', 'Women at tailgates, wine festivals and Oktoberfest.', 'Party Patch', 'Street interview', 'Social proof', '["What do you have tomorrow morning?", "Asking moms at a wine festival what time their alarm is set for.", "Oktoberfest question: what is your plan for tomorrow?"]', '[{"label": "Open \u00b7 0 to 3s", "text": "Mic in hand at a tailgate, wine festival or Oktoberfest. Ask women what they have tomorrow."}, {"label": "Middle", "text": "Rapid answers: soccer at 8, work, church, pickleball."}, {"label": "Close", "text": "Hand each one a patch: then you will want this."}]', NULL, 'Get a yes from everyone before you film them.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('67bb0308fb113c2a', 'act_1033194534145987', 'feccd9ea424d35e8', 0, 0, 1, 'live', 'Friendsgiving without the next-day regret', 'Friendsgiving is tonight and Thanksgiving prep is tomorrow, so the patch is at every place setting.', 'The friend hosting or going to Friendsgiving.', 'Party Patch', 'Group reaction', 'Belonging', '["Friendsgiving tonight. Thanksgiving prep tomorrow.", "The Friendsgiving table is set. There is a patch at every seat.", "Hosting tip: put a patch on every place card."]', '[{"label": "Open \u00b7 0 to 3s", "text": "A beautiful table, wine poured, friends arriving."}, {"label": "Middle", "text": "Close-up: a patch on every place card. Friends find theirs."}, {"label": "Close", "text": "Next morning: turkey prep, still smiling."}]', NULL, NULL, NULL, NULL);
